{
  "missing_information": [
    {
      "category": "actor",
      "gap": "It is unclear who the possible pickup persons are and how they are defined or authorized",
      "why_it_matters": "Knowing which actors can perform the pickup is essential to model handover logic and determine if authorization checks need to be automated"
    },
    {
      "category": "decision",
      "gap": "The criteria or trigger for changing the pickup person during the day are not described",
      "why_it_matters": "Understanding what causes a last-minute change drives the branching logic in the workflow and determines whether automated rerouting or notifications are needed"
    },
    {
      "category": "system",
      "gap": "No system or channel is mentioned for communicating pickup arrangements or changes (e.g., messaging app, school portal, phone call)",
      "why_it_matters": "The communication channel determines integration possibilities and whether notifications can be automated or must remain manual"
    },
    {
      "category": "output",
      "gap": "It is unclear how confirmation that the child arrived home safely is obtained and recorded",
      "why_it_matters": "The confirmation step is a key output of the workflow; without knowing its form, it is impossible to assess automation or audit trail options"
    },
    {
      "category": "exception",
      "gap": "There is no information about what happens if the designated pickup person cannot be reached or fails to collect the child",
      "why_it_matters": "Failure scenarios require fallback steps and possibly escalation paths, which significantly affect workflow design and risk management"
    },
    {
      "category": "manual_effort",
      "gap": "The effort involved in coordinating and confirming the pickup arrangement is not quantified (e.g., number of messages, calls, time spent)",
      "why_it_matters": "Quantifying manual effort helps prioritize which steps offer the highest automation value"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "Who are the people that may be authorized to pick up your child, and is there a fixed list or does it change each day?",
      "targets": ["actor"]
    },
    {
      "id": "Q2",
      "question": "What typically triggers a change in the pickup person during the day, and how do you decide who the replacement will be?",
      "targets": ["decision"]
    },
    {
      "id": "Q3",
      "question": "What channel or tool do you use to communicate pickup arrangements and any changes to the school or caregiver — for example, a messaging app, phone call, or school portal?",
      "targets": ["system"]
    },
    {
      "id": "Q4",
      "question": "How do you confirm that your child has arrived home safely — for example, does the caregiver send a message, do you call them, or is there some other signal?",
      "targets": ["output"]
    },
    {
      "id": "Q5",
      "question": "What do you do if the designated pickup person cannot be reached or does not arrive at the school in time?",
      "targets": ["exception"]
    },
    {
      "id": "Q6",
      "question": "On a typical day, how much time do you spend coordinating the pickup arrangement and following up to confirm the child is home?",
      "targets": ["manual_effort"]
    }
  ]
}
